    'Mentioned in a doc: “{quote}”': ['Mencionado en un documento: “{quote}”', 'Mencionado em um documento: “{quote}”', 'Mentionné dans un document : « {quote} »', 'In einem Dokument erwähnt: „{quote}“', 'ドキュメントで言及:「{quote}」', '在文档中提到：“{quote}”', '문서에서 언급: “{quote}”'],
    'Mentioned in {n} places: “{quote}”': ['Mencionado en {n} lugares: “{quote}”', 'Mencionado em {n} lugares: “{quote}”', 'Mentionné à {n} endroits : « {quote} »', 'An {n} Stellen erwähnt: „{quote}“', '{n} か所で言及:「{quote}」', '在 {n} 处提到：“{quote}”', '{n}곳에서 언급: “{quote}”'],
    'It came from {list}.': ['Viene de {list}.', 'Veio de {list}.', 'Cela vient de {list}.', 'Es kommt von {list}.', '出どころ: {list}。', '来源：{list}。', '출처: {list}.'],
